tion" value="duplicate_survey"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-secondary">Duplicar</button></form><form class="d-inline" method="post" action="index.php?p=admin&tab=encuestas" onsubmit="return confirm('¿Confirma el cambio de estado?')"><?=csrf_field()?><input type="hidden" name="action" value="survey_state"><input type="hidden" name="id" value="<?=$s['id']?>"><input type="hidden" name="estado" value="<?=$s['estado']==='publicada'?'cerrada':'publicada'?>"><button class="btn btn-sm btn-outline-warning"><?=$s['estado']==='publicada'?'Cerrar':'Publicar'?></button></form> <form class="d-inline" method="post" action="index.php?p=admin&tab=encuestas" onsubmit="return confirm('¿Eliminar definitivamente esta encuesta y todas sus respuestas?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_survey"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></div><h4 class="h5 mt-4">Encuestas privadas (solo personal)</h4><div class="table-responsive"><table class="table"><thead><tr><th>Encuesta</th><th>Acceso</th><th>Estado</th><th>Respuestas</th><th>Acciones</th></tr></thead><tbody><?php foreach($surveys as $s): if($s['publico']!=='personal') continue; $qs=$pdo->prepare('SELECT * FROM preguntas WHERE encuesta_id=? ORDER BY orden');$qs->execute([$s['id']]);$editQuestions=[];foreach($qs->fetchAll() as $qq){$op=$pdo->prepare('SELECT texto FROM opciones_pregunta WHERE pregunta_id=? ORDER BY orden');$op->execute([$qq['id']]);$editQuestions[]=['tipo'=>$qq['tipo'],'texto'=>$qq['enunciado'],'obligatoria'=>(bool)$qq['obligatoria'],'opciones'=>array_column($op->fetchAll(),'texto')];}$info=['id'=>$s['id'],'titulo'=>$s['titulo'],'descripcion'=>$s['descripcion'],'publico'=>$s['publico'],'estado'=>$s['estado']]; ?><tr><td><?=h($s['titulo'])?></td><td>Privada</td><td><?=h($s['estado'])?></td><td><?=$s['respuestas']?></td><td><a class="btn btn-sm btn-outline-primary" href="index.php?p=estadisticas&id=<?=$s['id']?>">Resultados</a> <a class="btn btn-sm btn-outline-success" href="index.php?p=exportar&id=<?=$s['id']?>">CSV</a><?php if((int)$s['respuestas']===0): ?> <button class="btn btn-sm btn-outline-secondary" onclick='editSurvey(<?=h(json_encode($info,JSON_HEX_APOS|JSON_HEX_QUOT))?>,<?=h(json_encode($editQuestions,JSON_HEX_APOS|JSON_HEX_QUOT))?>,<?=h(json_encode(selected_categories($pdo,'encuesta_categoria','encuesta_id',(int)$s['id'])))?>)'>Editar</button><?php endif; ?> <form class="d-inline" method="post" action="index.php?p=admin&tab=encuestas" onsubmit="return confirm('¿Eliminar definitivamente esta encuesta y todas sus respuestas?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_survey"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div>
